From 971d387c50337992dbca26239e8ea82dd3e3af01 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Thu, 26 Nov 2026 00:51:38 +0100
Subject: [PATCH] applets/notifications: add a shortcut to focus the latest
 notification

Popups could only be used with the mouse, so replying to a message meant
leaving the keyboard. A new global shortcut focuses the newest popup and
starts its inline reply if it has one; Escape hides the focused popup.

BUG: 439893
---
 applets/notifications/NotificationPopup.qml   | 26 ++++++++++++++++++-
 .../components/ActionContainer.qml            |  7 +++++
 .../components/ModelInterface.qml             |  1 +
 applets/notifications/global/Globals.qml      | 12 +++++++++
 applets/notifications/globalshortcuts.cpp     | 10 +++++++
 applets/notifications/globalshortcuts.h       |  2 ++
 6 files changed, 57 insertions(+), 1 deletion(-)

diff --git a/applets/notifications/NotificationPopup.qml b/applets/notifications/NotificationPopup.qml
index bfc68dfe8b..1979ecb804 100644
--- a/applets/notifications/NotificationPopup.qml
+++ b/applets/notifications/NotificationPopup.qml
@@ -34,6 +34,9 @@ NotificationsApplet.NotificationWindow {

     property var defaultActionFallbackWindowIdx

+    // Focused through the "Focus Latest Notification" global shortcut
+    property bool keyboardFocused: false
+
     signal expired
     signal hoverEntered
     signal hoverExited
@@ -50,7 +53,23 @@ NotificationsApplet.NotificationWindow {
     }

     // On wayland we need focus to copy to the clipboard, we change on mouse interaction until the cursor leaves
-    takeFocus: notificationItem.modelInterface.replying || focusListener.wantsFocus
+    takeFocus: notificationItem.modelInterface.replying || focusListener.wantsFocus || keyboardFocused
+
+    function focusFromKeyboard() {
+        keyboardFocused = true;
+        requestActivate();
+        if (modelInterface.hasReplyAction) {
+            modelInterface.beginReplyRequested();
+        } else {
+            mainItem.nextItemInFocusChain(true)?.forceActiveFocus(Qt.ShortcutFocusReason);
+        }
+    }
+
+    onActiveChanged: {
+        if (!active) {
+            keyboardFocused = false;
+        }
+    }

     visible: false

@@ -67,6 +86,8 @@ NotificationsApplet.NotificationWindow {
         acceptedButtons: Qt.AllButtons
         hoverEnabled: true
         onPressed: wantsFocus = true
+
+        Keys.onEscapePressed: notificationPopup.expired()
         onContainsMouseChanged: {
             wantsFocus = wantsFocus && containsMouse
             if (containsMouse) {
@@ -168,6 +189,9 @@ NotificationsApplet.NotificationWindow {
                     if (notificationItem.dragging || notificationItem.menuOpen || activateDefaultActionDropArea.containsAcceptableDrag) {
                         return false;
                     }
+                    if (notificationPopup.keyboardFocused) {
+                        return false;
+                    }
                     if (notificationItem.modelInterface.replying
                             && (notificationPopup.active || notificationItem.modelInterface.hasPendingReply)) {
                         return false;
diff --git a/applets/notifications/components/ActionContainer.qml b/applets/notifications/components/ActionContainer.qml
index a9b26eb6da..bcd1d116fa 100644
--- a/applets/notifications/components/ActionContainer.qml
+++ b/applets/notifications/components/ActionContainer.qml
@@ -29,6 +29,13 @@ PlasmaComponents3.StackView {
         currentItem.activate()
     }

+    Connections {
+        target: actionContainer.modelInterface
+        function onBeginReplyRequested() {
+            actionContainer.beginReply();
+        }
+    }
+
     pushEnter: Transition {
         NumberAnimation {
             property: "opacity"
diff --git a/applets/notifications/components/ModelInterface.qml b/applets/notifications/components/ModelInterface.qml
index b422c95b73..a08cd7fb0b 100644
--- a/applets/notifications/components/ModelInterface.qml
+++ b/applets/notifications/components/ModelInterface.qml
@@ -87,6 +87,7 @@ QtObject {
     signal openUrl(string url)
     signal fileActionInvoked(QtObject action)
     signal forceActiveFocusRequested
+    signal beginReplyRequested

     signal suspendJobClicked
     signal resumeJobClicked
diff --git a/applets/notifications/global/Globals.qml b/applets/notifications/global/Globals.qml
index 8e8e56f88d..c2a7d712da 100644
--- a/applets/notifications/global/Globals.qml
+++ b/applets/notifications/global/Globals.qml
@@ -795,8 +795,20 @@ QtObject {
         }
     }

+    function focusLatestPopup() {
+        let latestPopup = null;
+        for (let i = 0; i < popupInstantiator.count; ++i) {
+            const popup = popupInstantiator.objectAt(i);
+            if (popup && popup.visible && (!latestPopup || popup.modelInterface.time > latestPopup.modelInterface.time)) {
+                latestPopup = popup;
+            }
+        }
+        latestPopup?.focusFromKeyboard();
+    }
+
     property Notifications.GlobalShortcuts shortcuts: Notifications.GlobalShortcuts {
         onToggleDoNotDisturbTriggered: globals.toggleDoNotDisturbMode()
         onClearHistoryTriggered: plasmoidItem.clearNotificationHistoryAndShowOsd()
+        onFocusLatestNotificationTriggered: globals.focusLatestPopup()
     }
 }
diff --git a/applets/notifications/globalshortcuts.cpp b/applets/notifications/globalshortcuts.cpp
index c3613d49ad..106ba51e46 100644
--- a/applets/notifications/globalshortcuts.cpp
+++ b/applets/notifications/globalshortcuts.cpp
@@ -18,6 +18,7 @@ GlobalShortcuts::GlobalShortcuts(QObject *parent)
     : QObject(parent)
     , m_toggleDoNotDisturbAction(new QAction(this))
     , m_clearHistoryAction(new QAction(this))
+    , m_focusLatestNotificationAction(new QAction(this))
 {
     m_toggleDoNotDisturbAction->setObjectName(QStringLiteral("toggle do not disturb"));
     m_toggleDoNotDisturbAction->setProperty("componentName", QStringLiteral("plasmashell"));
@@ -36,6 +37,15 @@ GlobalShortcuts::GlobalShortcuts(QObject *parent)
     connect(m_clearHistoryAction, &QAction::triggered, this, &GlobalShortcuts::clearHistoryTriggered);

     KGlobalAccel::self()->setGlobalShortcut(m_clearHistoryAction, QKeySequence());
+
+    m_focusLatestNotificationAction->setObjectName(QStringLiteral("focus latest notification"));
+    m_focusLatestNotificationAction->setProperty("componentName", QStringLiteral("plasmashell"));
+    m_focusLatestNotificationAction->setText(i18nc("@action", "Focus Latest Notification"));
+    m_focusLatestNotificationAction->setIcon(QIcon::fromTheme(QStringLiteral("notifications")));
+    m_focusLatestNotificationAction->setShortcutContext(Qt::ApplicationShortcut);
+    connect(m_focusLatestNotificationAction, &QAction::triggered, this, &GlobalShortcuts::focusLatestNotificationTriggered);
+
+    KGlobalAccel::self()->setGlobalShortcut(m_focusLatestNotificationAction, QKeySequence());
 }

 GlobalShortcuts::~GlobalShortcuts() = default;
diff --git a/applets/notifications/globalshortcuts.h b/applets/notifications/globalshortcuts.h
index 60d097344d..64f614833e 100644
--- a/applets/notifications/globalshortcuts.h
+++ b/applets/notifications/globalshortcuts.h
@@ -26,8 +26,10 @@ public:
 Q_SIGNALS:
     void toggleDoNotDisturbTriggered();
     void clearHistoryTriggered();
+    void focusLatestNotificationTriggered();

 private:
     QAction *m_toggleDoNotDisturbAction;
     QAction *m_clearHistoryAction;
+    QAction *m_focusLatestNotificationAction;
 };
